async (dbRows, q) => {
    // ⚠️ `missingMigrationEmpty` answers with the `[{r:[]}]` sentinel, and `?? null` does
    // NOT catch an empty ARRAY — it is truthy, so an unmigrated database used to publish
    // `personSlug: []`, which the client reads as a resolved person and renders a dashboard
    // for. Take the value only when it is the string this lookup returns.
    const slugOrNull = (rows) =>
      typeof rows[0]?.r === "string" ? rows[0].r : null;
    const slug = s(q, "slug");
    if (slug) {
      const rows = await dbRows("SELECT candidate_person_slug($1) AS r", [
        slug,
      ]).catch(missingMigrationEmpty);
      // A slug is party-unique by construction, so there is never a set to choose from.
      return { body: { personSlug: slugOrNull(rows), namesakes: [] } };
    }
    const name = s(q, "name");
    if (!name) return { body: { personSlug: null, namesakes: [] } };
    // A ballot number, or no hint at all. `clampInt`'s floor turns `?party=`, `?party=0` and
    // `?party=-5` into ballot №1 — a real party — and any non-null party also excludes the
    // 16,054 rows where `party_num IS NULL` (every `mp-{id}` candidacy), so a bad value does
    // not merely narrow, it answers about the wrong ballot and hides every MP.
    const partyRaw = s(q, "party");
    const party = /^[1-9]\d?$/.test(partyRaw) ? Number(partyRaw) : null;
    // An election is a data-tree folder name, never free text.
    const electionRaw = s(q, "election");
    const election = /^\d{4}_\d{2}_\d{2}$/.test(electionRaw)
      ? electionRaw
      : null;
    const [byName, nameSet] = await Promise.all([
      // ⚠️ Falls back to the 2-arg signature rather than degrading to null: on a database
      // whose 085 predates the 3-arg form, `missingMigrationEmpty` would stop resolving even
      // the ~25.6k folds that name exactly one person — turning a hosting-before-migration
      // deploy into a REGRESSION on every bare-name candidate page rather than a no-op.
      dbRows("SELECT candidate_person_by_name($1, $2, $3) AS r", [
        name,
        party,
        election,
      ]).catch((e) => {
        if (e?.code !== "42883") return Promise.reject(e);
        logMissOnce(
          "cp:no-election-arg",
          "candidate_person_by_name(text,int,text) raised 42883 — either " +
            "085_person_elections.sql is not applied here, or something its body calls is " +
            "missing (translit_bg_latin → 000_search_fns.sql). Falling back to the " +
            "name+party lookup, which cannot disambiguate a shared name",
        );
        return dbRows("SELECT candidate_person_by_name($1, $2) AS r", [
          name,
          party,
        ]).catch(missingMigrationEmpty);
      }),
      dbRows("SELECT candidate_person_namesakes($1) AS r", [name]).catch(
        missingMigrationEmpty,
      ),
    ]);
    const namesakes = Array.isArray(nameSet[0]?.r) ? nameSet[0].r : [];
    return { body: { personSlug: slugOrNull(byName), namesakes } };
  }

async (dbRows, q) => {
    const ns = s(q, "ns");
    if (!ns) return { body: [] };
    const raw = s(q, "mpIds");
    // null = unscoped (whole ns); [] = a scope was asked for but is empty → zero makes.
    const mpIds = raw
      ? raw
          .split(",")
          .map((x) => parseInt(x, 10))
          .filter(Number.isFinite)
      : null;
    if (mpIds && mpIds.length === 0) return { body: [] };
    const rows = await dbRows(
      `SELECT COALESCE(
                jsonb_agg(
                  jsonb_build_object(
                    'make', make,
                    'mpCount', mp_count,
                    'vehicleCount', vehicle_count,
                    'sampleMpIds', sample_ids
                  ) ORDER BY mp_count DESC, vehicle_count DESC, make
                ),
                '[]'::jsonb
              ) AS r
       FROM (
         SELECT make,
                count(DISTINCT mp_id) AS mp_count,
                count(*) AS vehicle_count,
                (array_agg(DISTINCT mp_id ORDER BY mp_id))[1:6] AS sample_ids
         FROM mp_cars_table
         WHERE ns = $1 AND make IS NOT NULL
           AND ($2::int[] IS NULL OR mp_id = ANY($2))
         GROUP BY make
       ) g`,
      [ns, mpIds],
    ).catch(missingMigrationEmpty);
    return { body: rows[0]?.r ?? [] };
  }

async company(dbRows, q) {
    const eik = s(q, "eik");
    if (!eik) return { status: 400, body: { error: "missing eik" } };
    const [
      company,
      summary,
      officers,
      politicians,
      procurement,
      cabinets,
      debarred,
      funds,
      relationships,
      sectors,
      related,
      institution,
      geography,
      seatPlace,
      awarderProcurement,
      awarderAllTime,
      fundProjects,
      ngoDetails,
      awarderKindex,
      ngoFunding,
      awarderRiskGrade,
      supplierRiskGrade,
      corpusName,
      subsidies,
      retailChain,
      ngoSignals,
      ngoBoardLinks,
      nkid,
      cleanDelivery,
      declaredStakes,
    ] = await Promise.all([
      // ⚠️ 42703 (undefined_column), NOT the usual 42883/42P01 pair every other guarded
      // arm here tests. `tr_companies` is ancient, so this arm could never fail on a
      // missing RELATION — but adding a COLUMN gave it a migration dependency where there
      // was none, under a SQLSTATE no degrade helper in this file handles. And it shares
      // the route's single Promise.all, so rejecting here 500s the WHOLE company payload
      // — for every company AND every awarder, since CompanyDbScreen serves both.
      //
      // 003's only loader-side applier is `db:load:tr:pg`, ~34.9 min on cloud, so without
      // this a `deploy:db` landing first is a site-wide outage with a half-hour floor on
      // the recovery. Falling back to the pre-003 column list keeps the page whole.
      dbRows(
        "SELECT uic, name, legal_form, seat, subject_of_activity, status, funds_amount, funds_currency, entity_class, ngo_type FROM tr_companies WHERE uic = $1",
        [eik],
      ).catch((e) => {
        if (e?.code !== "42703") return Promise.reject(e);
        // Without this line, "003 never reached this database" is indistinguishable from
        // "this company registered no предмет на дейност" — on every company, silently.
        logMissOnce(
          "co:no-subject-column",
          "tr_companies.subject_of_activity absent — serving the company without it. " +
            "Apply 003: npx tsx scripts/db/apply_functions.ts 003_tr_search.sql",
        );
        return dbRows(
          "SELECT uic, name, legal_form, seat, NULL::text AS subject_of_activity, status, funds_amount, funds_currency, entity_class, ngo_type FROM tr_companies WHERE uic = $1",
          [eik],
        );
      }),
      dbRows(
        // DELIBERATELY UNSCOPED — "has this entity ever been a supplier, in any period?",
        // the sell-side twin of the awarderAllTime probe below. Everything else on this
        // route is windowed by from/to, and only 3.8% of the corpus's contract money sits
        // inside the default parliament window, so without an all-time figure the page
        // cannot tell a reader where the money they came looking for actually is.
        //
        // ⚠️ THREE FIELDS, THREE NAMED BASES, AND `contracts` IS NOT `contract_rows`.
        // `contracts` counts EVERY tag — it gates whether the page renders a procurement
        // body at all, so an amendment-only entity must still count. It is NOT the basis
        // of any money figure here (1864 vs 1860 on 130878827), and pairing it with the
        // contract-tag sum in one sentence — "N договора на стойност €X" — would state two
        // bases as one.
        //
        // ⚠️⚠️ `contract_rows` MUST MATCH `company_procurement.contract_count` EXACTLY —
        // `tag = 'contract' AND consortium_role IS DISTINCT FROM 'member'` (011, line 40).
        // Dropping the consortium clause is NOT a rounding difference: migration 087 moves
        // a joint award's whole value onto the synthetic carrier and ZEROES the members, so
        // member rows are €0 rows the money sum is blind to and a plain count is not.
        // Measured on 103895548 — 50 by the card, 176 without the clause — i.e. an all-time
        // note reading "176 договора" directly beside a "Договори 50" tile. 3,230 suppliers
        // are in that state. The €0 members stay IN `contracts_eur` precisely because they
        // are zero; only the count has to exclude them.
        `SELECT count(*)::int AS contracts,
                count(*) FILTER (WHERE tag = 'contract'
                  AND consortium_role IS DISTINCT FROM 'member')::int AS contract_rows,
                coalesce(sum(amount_eur) FILTER (WHERE tag = 'contract'), 0) AS contracts_eur
           FROM contracts WHERE contractor_eik = $1`,
        [eik],
      ),
      // Bounded: a few pathological holdings have thousands of officer rows —
      // the page previews a handful and links to the paginated officers table.
      dbRows("SELECT * FROM company_officers($1) LIMIT 500", [eik]),
      // `relations` (the full connections jsonb) rides along so the shared
      // political-links tile can render "(former)" / "declared stake N%" /
      // role labels without a second round-trip to the company-politicians route.
      dbRows(
        "SELECT politician, ref, kind, role, relations, total_eur FROM company_politicians WHERE eik = $1 ORDER BY total_eur DESC NULLS LAST LIMIT 200",
        [eik],
      ),
      dbRows("SELECT company_procurement($1, $2, $3) AS r", [
        eik,
        orNull(q, "from"),
        orNull(q, "to"),
      ]),
      dbRows("SELECT * FROM company_by_cabinet($1)", [eik]),
      dbRows("SELECT * FROM company_debarred($1)", [eik]),
      dbRows("SELECT * FROM fund_beneficiaries WHERE eik = $1", [eik]),
      dbRows("SELECT company_buyer_relationships($1) AS r", [eik]),
      dbRows("SELECT company_sectors($1) AS r", [eik]),
      dbRows("SELECT company_related($1) AS r", [eik]),
