                CASE WHEN cp.kind = 'mp'
                     THEN COALESCE(person_slug_redirect(replace(cp.ref, '/candidate/', '')),
                                   replace(cp.ref, '/candidate/', ''))
                     ELSE officials_person_slug(replace(cp.ref, '/officials/', ''))
