      // this must serve the page WITHOUT the tiles rather than 500 the whole crawler-walked
      // /person/{slug} (roles, politicians, procurement, everything).
      dbRows("SELECT person_procurement_by_company($1, $2, $3) AS r", [
        name,
        from,
        to,
