      dbRows("SELECT person_procurement_by_settlement($1, $2, $3) AS r", [
        name,
        from,
        to,
      ]).catch(missingMigrationEmpty),
    ]);
    return {
      body: {
        name,
        roles,
        politicians,
        procurement: procurement[0]?.r ?? null,
        cabinets,
        associates,
        byCompany: byCompany[0]?.r ?? [],
